using System;using System.Collections.Generic;using System.Drawing;using System.Globalization;using System.IO;using System.Linq;using System.Threading.Tasks;using System.Windows.Forms;
namespace Videira {public partial class VideiraSite {
 void MediaPage(){var root=PageRoot("Biblioteca de mídia");var tools=Buttons();var filter=new TextBox{Width=280,AccessibleName="Pesquisar imagens",Margin=new Padding(0,4,12,8)};tools.Controls.Add(filter);tools.Controls.Add(ActionButton("Atualizar",async()=>{await Reload();MediaPage();Notify("Biblioteca atualizada.");}));root.Controls.Add(tools);var count=new Label{AutoSize=true,Margin=new Padding(0,0,0,12)};root.Controls.Add(count);var grid=Grid();grid.Height=410;grid.MultiSelect=false;root.Controls.Add(grid);Action render=()=>{var rows=products.Where(p=>SiteApi.Read(p,"image_url")!=""&&SiteApi.Read(p,"name").IndexOf(filter.Text,StringComparison.CurrentCultureIgnoreCase)>=0).Select(p=>new ImageRow{Id=SiteApi.Read(p,"id"),Produto=SiteApi.Read(p,"name"),Imagem=SiteApi.Read(p,"image_url")}).ToList();grid.DataSource=rows;if(grid.Columns.Contains("Id")){grid.Columns["Id"].Visible=false;grid.Columns["Produto"].FillWeight=160;}count.Text=rows.Count+" imagens associadas a produtos • "+products.Count(p=>SiteApi.Read(p,"image_url")=="")+" produtos sem foto";};render();filter.TextChanged+=(s,e)=>render();grid.CellDoubleClick+=(s,e)=>{if(e.RowIndex>=0){var row=(ImageRow)grid.Rows[e.RowIndex].DataBoundItem;Editor(products.First(p=>SiteApi.Read(p,"id")==row.Id));}};root.Controls.Add(new Label{Text="Dê dois cliques para editar o produto e substituir sua imagem. Envie JPG, PNG ou WebP pelo editor.",AutoSize=true,ForeColor=Color.DimGray,Margin=new Padding(0,12,0,0)});dirty=false;}
 void CheckScreens(){string folder=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"screens-v2");Directory.CreateDirectory(folder);categories=new List<string>{"Tintos","Brancos","Espumantes"};terms=new List<CatalogTerm>{new CatalogTerm{Id="11111111-1111-1111-1111-111111111111",Name="Tintos",Kind="tipo",Parent=""},new CatalogTerm{Id="22222222-2222-2222-2222-222222222222",Name="Reserva",Kind="tipo",Parent="11111111-1111-1111-1111-111111111111"},new CatalogTerm{Id="33333333-3333-3333-3333-333333333333",Name="Merlot",Kind="uva",Parent=""},new CatalogTerm{Id="44444444-4444-4444-4444-444444444444",Name="Brasil",Kind="pais",Parent=""}};storeSettings=new Dictionary<string,object>{{"store_name","Videira Vinhoteca"},{"whatsapp","5545999056277"},{"primary_color","#73233a"}};products=Enumerable.Range(1,8).Select(i=>new Dictionary<string,object>{{"id",Guid.NewGuid().ToString()},{"name",i==1?"Vinho Tinto Reserva — exemplo de nome longo para conferir o layout":"Vinho de exemplo "+i},{"category",categories[i%3]},{"price",i%3==0?(object)null:(object)(89.9m+i)},{"country","Brasil"},{"grape","Merlot"},{"winery","Produtor de exemplo"},{"description","Dados fictícios usados somente para testar o layout."},{"image_url",i%2==0?"":"https://example.com/foto.jpg"},{"active",i%2==0},{"featured",i%3==0}}).ToList();foreach(int width in new[]{1024,1366}){Size=new Size(width,850);foreach(string view in new[]{"Painel","Produtos","Adicionar produto","Categorias","Mídia","Configurações","Entrar"}){dirty=false;if(view=="Entrar")LoginPage();else ShowPage(view);PerformLayout();FitPage();Application.DoEvents();SavePreview(Path.Combine(folder,width+"-"+view.Replace(" ","-")+".png"));foreach(var tabControl in Walk(body).OfType<TabControl>().ToArray()){for(int ti=0;ti<tabControl.TabPages.Count;ti++){tabControl.SelectedIndex=ti;Application.DoEvents();SavePreview(Path.Combine(folder,width+"-"+view.Replace(" ","-")+"-"+ti+".png"));}tabControl.SelectedIndex=0;}if(currentRoot!=null&&currentRoot.Width>body.ClientSize.Width-body.Padding.Horizontal)throw new Exception("Conteúdo ultrapassa largura: "+view);if(currentRoot!=null)CheckBounds(currentRoot,view);if(view=="Produtos"){var grid=currentRoot.Controls.OfType<DataGridView>().Single();if(grid.Rows.Count!=8)throw new Exception("Lista incompleta.");var filters=Walk(currentRoot).OfType<ComboBox>().ToArray();filters[0].SelectedIndex=2;if(grid.Rows.Count!=4)throw new Exception("Filtro de rascunhos falhou.");}}}products.Clear();ProductsPage();Application.DoEvents();var empty=currentRoot.Controls.OfType<DataGridView>().Single();if(empty.Rows.Count!=0)throw new Exception("Lista vazia inválida.");dirty=false;Dashboard();}
 void CheckBounds(Control parent,string view){foreach(Control c in parent.Controls){if(c.Visible&&!(parent is FlowLayoutPanel)&&!(c is Label)&&c.Right>parent.ClientSize.Width+2)throw new Exception("Controle cortado em "+view+": "+c.GetType().Name);CheckBounds(c,view);}}
}
public class ImageRow{public string Id{get;set;}public string Produto{get;set;}public string Imagem{get;set;}}
}
